mapper.select:
SELECT distinct p.id, p.program_id, p.name, p.data_type, p.label_type, p.description, p.create_by, p.update_by, p.create_time, p.update_time, p.del_flag FROM sys_program p LEFT JOIN sys_role_program rp ON p.id = rp.program_id WHERE p.del_flag = '0'
and p.name like concat('%', #{query.name}, '%')
and p.program_id = #{query.program_id}
and p.label_type = #{query.labelType}
and p.data_type = #{query.dataType}
and rp.role_id in
#{roleId}

SELECT EXISTS (SELECT 1 FROM sys_program
WHERE name = #{name}
)

mapper.update:
UPDATE sys_program
SET del_flag = '1', update_time = #{updateTime}
WHERE id = #{id}
